(() => {
 'use strict';
 const templates=[
  {title:'Free Fire Solo Showdown',game:'ff',mode:'Solo',capacity:48,banner:'assets/tournaments/free-fire-50x-red-prizes.png',rules:'Solo battle royale. Enter your correct Free Fire UID. Join the room before the start time. No hacks, teaming or unfair play. Rewards are credited after verified results.'},
  {title:'Free Fire Duo Battle',game:'ff',mode:'Duo',capacity:24,banner:'assets/tournaments/free-fire-10x-green-prizes.png',rules:'Duo battle royale. The team captain registers with their Free Fire UID. Join with your teammate before the start time. No hacks or unfair play. Rewards are credited to the registered captain after verified results.'},
  {title:'Free Fire Squad Clash',game:'ff',mode:'Squad',capacity:12,banner:'assets/tournaments/free-fire-100x-purple-prizes.png',rules:'Squad match. The team captain registers with their Free Fire UID. Bring your squad into the room before the start time. No hacks or unfair play. Rewards are credited to the registered captain after verified results.'}
 ];
 const stateName={draft:'Draft · not visible to players',open:'Published · registration open',live:'Match is running',completed:'Completed',cancelled:'Cancelled'};
 function render(host,rows,api){const {esc,money,date}=api;host.innerHTML=`<section class="tm-heading"><div><h2>Create a tournament in 3 steps</h2><p>Choose a template → set date, time & prizes → publish.</p></div><button id="admin-create" class="primary">+ New tournament</button></section><h3 class="tm-section-title">Ready-to-use Free Fire templates</h3><div class="tm-templates">${templates.map((t,i)=>`<article><img src="${t.banner}" alt="${esc(t.title)}"><div><h3>${esc(t.title)}</h3><p>${t.mode} · ${t.capacity} registration slots</p><button class="primary" data-template="${i}">Use this template</button></div></article>`).join('')}</div><p class="tm-help">Templates already include the banner, format and rules. Update fees, reward budget and timing before publishing. PUBG templates will become available when PUBG launches.</p><div class="tm-heading tm-manage-heading"><div><h2>Your tournaments</h2><p>Saved drafts and published matches. Use “Copy as new” to run another match with the same settings.</p></div><button id="tm-refresh">Refresh matches</button></div><div class="tm-matches">${rows.length?rows.map((r,i)=>`<article class="tm-match"><img src="${esc(r.banner)}" alt=""><div class="tm-match-content"><span class="status ${esc(r.status)}">${esc(stateName[r.status]||r.status)}</span><h3>${esc(r.title)}</h3><p>${esc(r.mode)} · ${esc(date(r.starts_at))} IST</p><div class="tm-metrics"><span>Entry<strong>${money(r.entry_fee)}</strong></span><span>Reward budget<strong>${money(r.prize_pool)}</strong></span><span>Slots<strong>${esc(r.capacity)}</strong></span></div><div class="tm-actions">${!['completed','cancelled'].includes(r.status)?`<button data-edit="${i}">Edit settings</button>${r.status==='draft'?`<button data-publish="${i}" class="primary">Publish</button>`:''}${r.status==='open'?`<button data-registration="${i}">${r.registration_closed?'Reopen registration':'Close registration'}</button><button data-start="${i}" class="primary">Start match</button>`:''}`:''}<button data-players="${i}">${r.status==='live'?'1st / 2nd prizes':'Players & prizes'}</button><button data-copy="${i}">Copy as new</button>${!['completed','cancelled'].includes(r.status)?`<button data-cancel="${i}">Cancel & refund</button>`:''}${r.status==='completed'?`<button class="danger" data-delete="${i}">Delete tournament</button>`:''}${r.status==='live'?`<button data-complete="${i}">Finish match</button>`:''}</div></div></article>`).join(''):'<div class="empty"><h3>No tournaments created yet</h3><p>Choose a template above to create your first match.</p></div>'}</div><div class="pagination"><button id="tm-prev" ${api.page===0?'disabled':''}>Previous</button><span>${api.total} tournaments · Page ${api.page+1}</span><button id="tm-next" ${(api.page+1)*50>=api.total?'disabled':''}>Next</button></div>`;
  host.querySelector('#admin-create').onclick=()=>editor({...templates[0]},api);host.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>editor({...templates[Number(b.dataset.template)]},api));host.querySelector('#tm-refresh').onclick=api.reload;host.querySelector('#tm-prev').onclick=()=>api.changePage(-1);host.querySelector('#tm-next').onclick=()=>api.changePage(1);
  for(const [attr,fn] of [['delete',r=>remove(r,api)],['registration',r=>registration(r,api)],['edit',r=>editor(r,api)],['copy',r=>editor({...r,id:undefined,status:'draft',registration_closed:false,starts_at:undefined,room_id:'',room_password:'',room_link:''},api)],['publish',r=>confirm(r,'open',api)],['start',r=>confirm(r,'live',api)],['complete',r=>confirm(r,'completed',api)],['cancel',r=>confirm(r,'cancelled',api)],['players',r=>api.players(r)]])host.querySelectorAll(`[data-${attr}]`).forEach(b=>b.onclick=()=>fn(rows[Number(b.dataset[attr])]));
 }
 function remove(r,api){const d=api.modal('Delete completed tournament'),box=d.querySelector('.record-actions');box.innerHTML='<h3>'+api.esc(r.title)+'</h3><p>This completed tournament will be removed from the tournament lists. Player registrations, results and wallet history will remain available.</p><button type="button" class="danger" data-confirm>Delete tournament</button><p class="error" role="alert"></p>';box.querySelector('[data-confirm]').onclick=async e=>{e.currentTarget.disabled=true;try{await api.remove(r);d.close();await api.reload();}catch(err){box.querySelector('.error').textContent=err.message;e.currentTarget.disabled=false;}};}
 function registration(r,api){const closed=!r.registration_closed,d=api.modal(closed?'Close registration':'Reopen registration'),box=d.querySelector('.record-actions');box.innerHTML='<p>'+api.esc(r.title)+'</p><p>'+(closed?'Stop new registrations. Existing players remain registered; no fees are refunded.':'Allow registrations while slots are available. The scheduled time does not close registration.')+'</p><button data-confirm class="primary">'+(closed?'Close registration':'Reopen registration')+'</button><p class="error" role="alert"></p>';box.querySelector('[data-confirm]').onclick=async e=>{e.currentTarget.disabled=true;try{await api.save({...payload(r,r.status),registration_closed:closed});d.close();await api.reload();}catch(err){box.querySelector('.error').textContent=err.message;e.currentTarget.disabled=false;}};}
 function payload(r,status){return {id:r.id,title:r.title,game:r.game,mode:r.mode,status,banner:r.banner,entry_fee:Number(r.entry_fee),prize_pool:Number(r.prize_pool),capacity:Number(r.capacity),starts_at:r.starts_at,registration_closed:!!r.registration_closed,rules:r.rules||'',room_id:r.room_id||'',room_password:r.room_password||'',room_link:r.room_link||''};}
 function editor(r,api){const {esc,field,area}=api,existing=!!r.id,d=api.modal(existing?'Edit tournament':'Create from template');d.classList.add('tm-editor');const box=d.querySelector('.record-actions');box.innerHTML=`<p class="tm-form-intro">${esc(r.mode)} · ${r.game==='pubg'?'PUBG':'Free Fire'} · Banner and rules are ready. Fill the settings below.</p><img class="tm-banner-preview" src="${esc(r.banner)}" alt="Tournament banner"><form><div class="form-grid">${field('title','Tournament name',r.title,'text','required minlength="3" maxlength="100"')}${field('entry_fee','Entry fee per registration (₹)',r.entry_fee??'','number','required min="0" max="100000" step="0.01"')}${field('prize_pool','Total rewards you will pay (₹)',r.prize_pool??0,'number','required min="0" max="10000000" step="0.01"')}${field('capacity','Registration slots',r.capacity,'number','required min="1" max="1000"')}${window.ColorWinAdminDate.render('starts_at','Choose match date & time',r.starts_at)}<label class="full">Type time directly (optional)<input data-direct-time placeholder="7:30 PM or 19:30" autocomplete="off"><small data-time-error>Choose the day in the calendar, then enter the time. All times are IST.</small></label><details class="full tm-advanced"><summary>Room details & match rules</summary><div class="form-grid">${field('room_link','Room invite link (HTTPS)',r.room_link||'','url','maxlength="2000" placeholder="https://ffshare.garena.com/…"')}${field('room_id','Room ID',r.room_id||'','text','maxlength="100"')}${field('room_password','Room password',r.room_password||'','text','maxlength="100"')}${area('rules','Match rules',r.rules,'maxlength="5000"')}</div><p>Room details are visible only to registered players after you start the match.</p></details></div><p class="tm-form-summary">${existing?'Save changes to this match.':'Save as a draft to prepare privately, or publish to let players register.'} Entry fee and rewards are in rupees.</p><div class="tm-form-buttons">${!existing||r.status==='draft'?'<button type="submit" data-save="draft">Save draft</button><button type="submit" data-save="open" class="primary">Publish tournament</button>':'<button type="submit" class="primary">Save changes</button>'}</div><p class="error" role="alert"></p></form>`;const form=box.querySelector('form');window.ColorWinAdminDate.bind(form);
  form.querySelector('[data-direct-time]').oninput=e=>{const raw=e.target.value.trim(),match=raw.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)?$/i),hint=form.querySelector('[data-time-error]');if(!raw){e.target.dataset.invalid='';hint.textContent='Choose the day in the calendar, then enter the time. All times are IST.';return;}e.target.dataset.invalid='';if(!match||Number(match[2])>59||(match[3]?Number(match[1])<1||Number(match[1])>12:Number(match[1])>23)){e.target.dataset.invalid='true';hint.textContent='Use a time such as 7:30 PM or 19:30.';return;}let h=Number(match[1]);if(match[3])h=h%12+(match[3].toUpperCase()==='PM'?12:0);const choose=(el,value)=>{try{el.value=String(value);if(el.value===String(value))return;}catch{}el.querySelectorAll('option').forEach(o=>{if(o.value===String(value))o.setAttribute('selected','');else o.removeAttribute('selected');});};choose(form.querySelector('[data-hour]'),h%12||12);choose(form.querySelector('[data-minute]'),Number(match[2]));choose(form.querySelector('[data-period]'),h>=12?'PM':'AM');form.querySelector('[data-hour]').dispatchEvent(new Event('change'));hint.textContent='Time applied to the calendar · IST';};
  form.onsubmit=async e=>{e.preventDefault();if(!form.reportValidity())return;const buttons=form.querySelectorAll('[type=submit]');buttons.forEach(b=>b.disabled=true);try{if(form.querySelector('[data-direct-time]').dataset.invalid)throw Error('Enter a valid time, such as 7:30 PM');const values=Object.fromEntries(new FormData(form)),starts=window.ColorWinAdminDate.toIso(values.starts_at),status=e.submitter?.dataset.save||r.status||'draft';const data={...payload(r,status),...values,starts_at:starts};if(!existing)delete data.id;await api.save(data);d.close();await api.reload();}catch(err){form.querySelector('.error').textContent=err.message;}finally{buttons.forEach(b=>b.disabled=false);}};
 }
 function confirm(r,status,api){const d=api.modal(status==='live'?'Start this match':status==='open'?'Publish this tournament':status==='cancelled'?'Cancel & refund':'Finish this match'),box=d.querySelector('.record-actions');box.innerHTML=`<h3>${api.esc(r.title)}</h3><p>${status==='live'?'Registered players can use Join room once the match is live. Add the Free Fire room invite link in Edit settings first.':status==='open'?'This tournament will appear on the user website and accept registrations.':status==='cancelled'?'This cancels the match and refunds paid registration fees to the players. This cannot be undone.':'Registration stays closed. You can publish verified player results and rewards from 1st / 2nd prizes.'}</p><button class="primary" data-confirm>${status==='live'?'Start match now':status==='open'?'Publish now':status==='cancelled'?'Confirm cancellation & refunds':'Mark completed'}</button><p class="error" role="alert"></p>`;box.querySelector('[data-confirm]').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{if(status==='live'&&(!r.room_link&&(!r.room_id||!r.room_password)))throw Error('Add the Room ID and password or a room invite link in Edit settings before starting');await api.save(payload(r,status));d.close();await api.reload();}catch(err){box.querySelector('.error').textContent=err.message;b.disabled=false;}};}
 window.ColorWinAdminTournaments={render,templates};
})();
